import { CARDS, FACTIONS, LANES, EVENTS, HEROES, ART, CARD_SET } from '/shared/cards.js';
import { power, combatAttack } from '/shared/engine.js';
import { ECONOMY, CONTRACTS, DECK_RULES, analyzeDeck, cardBalance, cardLimit, countCards, ownedCardCount, validateDeck } from '/shared/progression.js';
import { playSound, toggleSound, soundEnabled, animateEvents, captureCombatFrame } from '/effects.js';

import { CARD_ART } from '/shared/art-manifest.js';
import { renderRealms } from '/realms-ui.js';
const app=document.querySelector('#app');
let worldOpen=false,realmData=null,realmFocus=null,realmTab='map',realmPolling=false,modalHistory=[],cardSearch='',onlyOwned=false,packState='sealed',revealedSlots=new Set();
const rarityNames={common:'COMUM',uncommon:'INCOMUM',rare:'RARA',epic:'ÉPICA',legendary:'LENDÁRIA'};
const effectNames={lifesteal:'DRENAR',bleed:'SANGRAMENTO',guard:'GUARDA',overwhelm:'TRANSBORDO',fury:'FRENESI',pierce:'PERFURAR',mend:'RESTAURAR',focus:'FOCO',rally:'REFORÇO'};
function closeModal(){modal=modalHistory.pop()||null;render();}
function inspectCard(id){if(modal==='decks')deckDraftName=document.querySelector('#deck-name')?.value||deckDraftName;modalHistory.push(modal);modal='card:'+id;render();}
async function openRealms(){await guarded(async()=>{await ensureProfile();realmData=await api('/realms');worldOpen=true;room=null;modal=null;selected=null;realmFocus=realmData.player.location;});}
async function doRealmAction(type,extra={}){await guarded(async()=>{try{realmData=await api('/realms/actions','POST',{type,version:realmData.player.version,...extra});profile=realmData.profile;if(['travel','retreat'].includes(type)){realmFocus=realmData.player.location;playSound('start');}else playSound('loot');}catch(e){realmData=await api('/realms');throw e;}});}
async function realmEncounter(){await guarded(async()=>{room=await api('/realms/encounter','POST',{version:realmData.player.version});selected=null;modal=null;remember();});}
function searchTools(){return '<div class="arsenal-search"><span>⌕</span><input id="card-search" data-card-search placeholder="Nome, efeito ou sinergia…" value="'+esc(cardSearch)+'" aria-label="Buscar cartas"><button data-owned-filter aria-pressed="'+onlyOwned+'">'+(onlyOwned?'✓ MINHA COLEÇÃO':'TODAS AS CARTAS')+'</button></div>';}
function matchesSearch(c){return (c.name+' '+c.text+' '+(c.tags||[]).join(' ')).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(cardSearch.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())&&(!onlyOwned||ownedCardCount(c.id,profile?.collection||{},profile?.items||[])>0);}

let token=localStorage.getItem('bloodmoon.profile'),profile=null,room=null;
let faction=localStorage.getItem('bloodmoon.faction')||'vampire',selected=null,busy=false,modal=null,filter='all',lastRoom=sessionStorage.getItem('bloodmoon.room'),polling=false,pointerDrag=null,suppressedCardClick=null,editingDeckId=null,editingDeckFaction='vampire',deckDraft=null,deckDraftName='',packReveal=[],duelRisk='covenant',marketTab='market',marketOffers=[],marketItems=[];
if(!FACTIONS[faction])faction='vampire';
let toastTimer;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=(id,cls='')=>{const hero={vampire:'vesper',werewolf:'kael',boss:'mordrath'},src=CARD_ART[id]||(hero[id]?'/assets/avatars/'+hero[id]+'.png':null);return src?'<img class="art image-art '+cls+'" src="'+src+'" alt="" aria-hidden="true" loading="lazy" decoding="async">':'<span class="art art-'+(ART[id]??14)+' prototype-art '+cls+'" aria-hidden="true"></span>';};
const icon={unit:'ALIADO',spell:'RITUAL',equipment:'EQUIPAMENTO'};
const gearBadges=items=>(items||[]).map(item=>{const name=CARDS[item.cardId]?.name||'Relíquia',durability=item.itemId?profile?.items?.find(x=>x.id===item.itemId)?.durability:null;return `<span class="gear-badge" title="${esc(name)}${durability!==null&&durability!==undefined?` · ${durability}/${ECONOMY.gearDurability} usos`:''}">${art(item.cardId)}<b>${durability!==null&&durability!==undefined?durability:'◆'}</b></span>`;}).join('');
const heroes=p=>p.boss?{name:'Mordrath',title:'O Rei Sepultado',skill:'Dilacerar',description:'2 recursos · ataque de 3 de dano.',ultimate:'Fúria Ancestral'}:HEROES[p.faction];
function toast(message){document.querySelector('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.querySelector('#toast').textContent='',4500);}
async function api(route,method='GET',data){const r=await fetch(`/api${route}`,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},...(data?{body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw new Error(result.error||'Servidor indisponível.');return result;}
async function ensureProfile(){if(profile)return;profile=await api('/profile','POST',{name:'Caçador',faction});token=profile.id;localStorage.setItem('bloodmoon.profile',token);}
function remember(){if(room){lastRoom=room.roomId;sessionStorage.setItem('bloodmoon.room',lastRoom);}}
const canAct=()=>room&&!busy&&!room.waiting&&room.phase==='playing'&&room.turn===room.seat&&!room.players[room.seat].passed;
function card(id,uid='',i=0,n=1){const c=CARDS[id],active=selected?.uid===uid&&uid,available=!uid||(canAct()&&room.players[room.seat].energy>=c.cost),handItem=uid&&room?.players[room.seat].hand.find(x=>x.uid===uid),durability=handItem?.itemId?profile?.items?.find(x=>x.id===handItem.itemId)?.durability:null;return `<button class="game-card ${c.faction} rarity-${c.rarity} ${active?'selected':''} ${available?'affordable':'unaffordable'}" ${uid?`data-card="${uid}" draggable="false"`:`data-inspect="${id}"`} data-preview="${id}" style="--angle:${(i-(n-1)/2)*3}deg;--lift:${Math.abs(i-(n-1)/2)*3}px;--order:${i}" aria-label="${esc(c.name)}. Custo ${c.cost}. ${esc(c.text)}" ${uid&&!available?'aria-disabled="true"':''}>${art(id)}<span class="card-frame"></span><b class="cost-gem">${c.cost}</b><span class="card-rarity">◆</span>${durability!==null?`<span class="gear-durability" title="Durabilidade do equipamento">⚒ ${durability}/${ECONOMY.gearDurability}</span>`:''}<div class="card-caption"><small>${icon[c.type]}</small><strong>${c.name}</strong><span>${c.keyword==='lifesteal'?'DRENAR':c.keyword==='bleed'?'SANGRAR':c.keyword==='guard'?'GUARDA':c.keyword==='overwhelm'?'TRANSBORDO':c.keyword==='fury'?'FRENESI':c.synergy?'SINERGIA':c.type==='unit'?'PRONTO PARA ATACAR':c.type==='equipment'?`${effectNames[c.gearEffect]||'RELÍQUIA'} · EQUIPÁVEL`:'MAGIA INSTANTÂNEA'}</span></div>${c.type==='unit'?`<b class="stat attack-stat">${c.attack}</b><b class="stat health-stat">${c.health}</b>`:c.type==='equipment'?`<b class="stat attack-stat">+${c.attack}</b><b class="stat health-stat">+${c.health}</b>`:'<span class="spell-seal">✦</span>'}</button>`;}
function controls(){return `<div class="corner-controls"><button data-sound class="icon-button" aria-label="${soundEnabled()?'Desativar':'Ativar'} som" title="Som">${soundEnabled()?'♫':'♪'}</button><button data-fullscreen class="icon-button" aria-label="Tela cheia" title="Tela cheia">⛶</button><button data-modal="guide" class="icon-button" aria-label="Como jogar" title="Como jogar">?</button>${room?'<button data-modal="pause" class="icon-button" aria-label="Menu da partida">☰</button>':''}</div>`;}
function render(){document.body.classList.toggle('in-battle',!!room);document.body.classList.toggle('in-realms',worldOpen&&!room);app.innerHTML=(room?battle():worldOpen?renderRealms(realmData,realmFocus,realmTab,busy):lobby())+modalHTML();if(!room&&!worldOpen){const nav=document.querySelector('.lobby-bottom nav');if(nav)nav.innerHTML=`<button data-modal="collection">▥ <span>ARSENAL</span><small>${Object.values(profile?.collection||{}).reduce((a,n)=>a+n,0)+Object.values(profile?.items||[]).length} CARTAS</small></button><button data-modal="decks">♜ <span>DECKS</span><small>${profile?.decks?.length||0} LISTAS</small></button><button data-modal="boosters">✦ <span>BOOSTERS</span><small>${profile?.coins||0} MARCAS</small></button><button data-modal="market">⚖ <span>MERCADO</span><small>${profile?.items?.length||0} ITENS</small></button><button data-modal="contracts">⚒ <span>CONTRATOS</span><small>${profile?.dust||0} FRAGMENTOS</small></button><button data-modal="legacy">♛ <span>LEGADO</span><small>${profile?.trophies?.length||0} TROFÉUS</small></button>`;const badge=document.querySelector('.player-badge small');if(badge)badge.textContent=`${profile?.xp||0} XP · ${profile?.wins||0} vitórias · ${profile?.coins||0} MARCAS`;const build=document.querySelector('.build-label');if(build)build.innerHTML=`EDIÇÃO ${CARD_SET.symbol} · ${Object.keys(CARDS).length} CARTAS <i></i>`;}mountCardPreview();document.querySelector('#card-preview')?.classList.remove('visible');bindHover();bindInspectionTilt();}
function lobby(){const h=HEROES[faction];return `<main class="lobby ${faction}"><div class="scene-bg"></div><div class="fog fog-one"></div><div class="fog fog-two"></div><div class="embers" aria-hidden="true">${'<i></i>'.repeat(12)}</div><header class="lobby-header"><span class="season-label"><i></i> CRÔNICAS DE VÉSPERA <small>CAPÍTULO I · O REI SEPULTADO</small></span>${controls()}</header><section class="lobby-title"><p>UM JURAMENTO ESCRITO EM SANGUE</p><h1>BLOOD<span>MOON</span></h1><div class="title-rule"><i></i> SANGUE & FÚRIA <i></i></div></section><section class="character-stage" aria-label="Seu líder">${art(faction,'character-portrait')}<div class="portrait-rune"></div><div class="character-name"><small>${FACTIONS[faction].name}</small><h2>${h.name}</h2><p>${h.title}</p></div></section><section class="lobby-actions"><p class="overline">ESCOLHA QUEM CAÇA ESTA NOITE</p><div class="faction-switch">${Object.keys(FACTIONS).map(id=>`<button data-faction="${id}" class="${id===faction?'active':''}" aria-pressed="${id===faction}">${art(id)}<span>${id==='vampire'?'VAMPIROS':'LOBISOMENS'}<small>${id==='vampire'?'Drene. Execute. Reine.':'Persiga. Dilacere. Devore.'}</small></span></button>`).join('')}</div><button class="hunt-button" data-start="practice" ${busy?'disabled':''}><small>DUELO CONTRA A IA</small><span>INICIAR CAÇADA</span><b>⚔</b></button><button class="dungeon-button" data-start="dungeon" ${busy?'disabled':''}>${art('boss')}<span><small>DUNGEON · CHEFE</small>O Rei Sepultado</span><b>↗</b></button><button class="realm-entry" data-open-realms><img src="/assets/world/vespera-map.png" alt=""><span><small>UMA AVENTURA ALÉM DA ARENA</small>REINOS DE VÉSPERA<em>MUNDO PERSISTENTE · EXPLORAR ↗</em></span></button><button class="duel-button" data-modal="duel">DUELO ONLINE <span>1 × 1</span></button>${lastRoom?'<button class="resume-button" data-resume>↻ RETOMAR ÚLTIMA PARTIDA</button>':''}<p class="lobby-hint">Invoque aliados. Escolha suas presas. Liberte o frenesi.</p></section><div class="lobby-bottom"><div class="player-badge"><span class="player-level">${profile?.level||1}</span><div><strong>${esc(profile?.name||'Caçador')}</strong><small>${profile?.xp||0} XP · ${profile?.wins||0} vitórias</small></div></div><nav><button data-modal="collection">▥ <span>ARSENAL</span><small>${Object.keys(CARDS).length} CARTAS</small></button><button data-modal="legacy">♜ <span>LEGADO</span><small>${profile?.trophies?.length||0} TROFÉUS</small></button></nav><span class="build-label">ALPHA 0.4 <i></i></span></div></main>`;}
function hero(p,seat,enemy=false){const h=heroes(p),ownGearTarget=!enemy&&selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'&&(p.heroGear||[]).length<1,target=enemy&&selected&&(selected.kind==='skill'||selected.kind==='ultimate'||(selected.kind==='attack'&&room.players[seat].lanes[selected.lane].length===0))||ownGearTarget,targetLabel=ownGearTarget?'EQUIPAR':target&&selected?.kind==='attack'?'ATACAR LÍDER':target&&selected?.kind==='ultimate'?'SUPREMA':target?'ALVO':'';return `<div class="hero ${enemy?'enemy-hero':'player-hero'} ${p.faction}" data-hero="${seat}"><div class="hero-meta"><small>${p.boss?'CHEFE DE DUNGEON':enemy?'RIVAL':'SEU LÍDER'} ${p.passed?'· ENCERROU':''}</small><strong>${h.name}</strong><span>${h.title}</span></div><button class="hero-portrait ${target?'valid-target':''} ${ownGearTarget?'gear-target':''}" data-target="hero" data-seat="${seat}" ${!target?'tabindex="-1"':''} aria-label="${ownGearTarget?'Equipar item em ':target?'Atacar ':'Líder '}${h.name}, ${p.health} de vida">${art(p.boss?'boss':p.faction)}<b class="hero-health">${Math.max(0,p.health)}</b><span class="hero-ring"></span>${targetLabel?`<span class="target-cue ${ownGearTarget?'equip-cue':''}">${targetLabel}</span>`:''}${p.heroGear?.length?`<span class="hero-gear-display">${gearBadges(p.heroGear)}</span>`:''}</button><span class="hero-life-track" aria-label="${p.health} de ${p.maxHealth||24} vida"><i style="--hp:${Math.max(0,Math.min(100,(p.health/(p.maxHealth||24))*100))}%"></i></span><div class="hero-renown"><b>✦ ${p.renown}<small>/12</small></b><span>RENOME</span></div></div>`;}
function tokenUnit(u,lane,seat){const mine=seat===room.seat,c=CARDS[u.cardId];let target=false;
  if(selected&&canAct()){if(selected.kind==='attack')target=!mine&&lane===selected.lane;else if(['skill','ultimate'].includes(selected.kind))target=!mine;else if(selected.kind==='card'){const card=CARDS[selected.cardId];target=mine?(card.type==='equipment'&&u.equipment<2||['pounce','rally','guard'].includes(card.effect)):['damage','execute','rend','drain'].includes(card.effect);}}
  const targetVerb=selected?.kind==='attack'?'ATACAR':selected?.kind==='ultimate'?'EXECUTAR':selected?.kind==='skill'?'HABILIDADE':selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'?'EQUIPAR':selected?.kind==='card'&&CARDS[selected.cardId]?.effect==='pounce'?'SALTO':selected?.kind==='card'&&CARDS[selected.cardId]?.effect==='rally'?'REFORÇAR':selected?.kind==='card'&&CARDS[selected.cardId]?.effect==='guard'?'PROTEGER':'ALVO';
  return `<button class="fighter ${c.faction} ${mine?'allied':'hostile'} ${u.ready!==false?'ready':'exhausted'} ${target?'valid-target':''} ${selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'&&target?'equipment-target':''} ${selected?.uid===u.uid?'chosen-fighter':''}" data-unit="${u.uid}" data-seat="${seat}" data-lane-id="${lane}" data-preview="${u.cardId}" aria-label="${c.name}, ataque ${combatAttack(u)}, vida ${u.health}, nível ${u.level||1}${mine&&u.ready!==false?', pronto para atacar':''}">${art(u.cardId)}<span class="fighter-bevel"></span><span class="fighter-name">${c.name}</span><b class="fighter-attack">${combatAttack(u)}</b><b class="fighter-health">${u.health}</b><span class="fighter-level">${(u.level||1)>1?'★':''} ${u.level||1}</span>${target?`<span class="target-cue ${selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'?'equip-cue':''}">${targetVerb}</span>`:''}${u.bleed?'<span class="bleed" title="Sangrando">♦</span>':''}${u.equipment?`<span class="equipment-pips">${'◆'.repeat(u.equipment)}</span>`:''}${u.gearItems?.length?`<span class="gear-status" aria-label="${u.gearItems.length} equipamentos">${gearBadges(u.gearItems)}</span>`:''}${mine?`<span class="ready-label">${u.ready!==false?'⚔':'✓'}</span>`:''}</button>`;
}
function battle(){const me=room.players[room.seat],enemy=room.players[1-room.seat],h=HEROES[me.faction],ready=canAct(),event=EVENTS[room.round-1];
  const instruction=room.waiting?'COMPARTILHE O CÓDIGO PARA COMEÇAR':busy?'O SANGUE ESTÁ SENDO DERRAMADO…':room.phase==='finished'?'A CAÇADA TERMINOU':!ready?'AGUARDE SEU RIVAL':!selected?'JOGUE UMA CARTA OU CLIQUE EM UM ALIADO PARA ATACAR':selected.kind==='attack'?'ESCOLHA UMA PRESA NA MESMA FRENTE':selected.kind==='skill'||selected.kind==='ultimate'?'ESCOLHA UM INIMIGO OU O LÍDER RIVAL':CARDS[selected.cardId].type==='equipment'?'EQUIPE UM ALIADO OU SEU LÍDER':['pounce','rally','guard'].includes(CARDS[selected.cardId].effect)?'ESCOLHA O ALIADO QUE RECEBERÁ O EFEITO':['damage','execute','rend','drain'].includes(CARDS[selected.cardId].effect)?'ESCOLHA UM COMBATENTE INIMIGO':'ESCOLHA UMA FRENTE PARA INVOCAR';
  const turnMode=room.waiting?'waiting':room.phase==='finished'?'finished':ready?'active':me.passed?'locked':'enemy',turnTitle=turnMode==='active'?(enemy.passed?'ÚLTIMA AÇÃO':'SUA VEZ'):turnMode==='enemy'?'TURNO DO RIVAL':turnMode==='locked'?'VOCÊ ENCERROU':turnMode==='waiting'?'AGUARDANDO RIVAL':'CAÇADA ENCERRADA';
  return `<main class="arena ${me.faction}" aria-label="Arena de combate"><div class="scene-bg"></div><div class="arena-vignette"></div><div class="fog fog-one"></div><div class="embers" aria-hidden="true">${'<i></i>'.repeat(12)}</div><header class="battle-top"><div class="battle-brand">BLOOD<span>MOON</span><small>${room.mode==='dungeon'?'O SEPULCRO DO REI':'FORTALEZA DA ÚLTIMA NOITE'}</small></div>${controls()}</header><div class="round-medallion"><b>${room.round}</b><span>RODADA</span><small>DE 8</small></div><div class="event-pill"><span>☾</span><div><strong>${event.name}</strong><small>${event.lane?`+1 Renome · ${LANES.find(l=>l.id===event.lane).name}`:'A noite pertence aos que sobrevivem'}</small></div></div>${hero(enemy,1-room.seat,true)}<div class="enemy-hand" aria-label="${enemy.handCount} cartas na mão rival">${Array.from({length:Math.min(enemy.handCount,10)},(_,i)=>`<i style="--back-angle:${(i-(enemy.handCount-1)/2)*5}deg">◈</i>`).join('')}</div><div class="battlefield"><div class="battlefield-surface"></div>${LANES.map((l,li)=>`<section class="battle-lane lane-${l.id}" data-zone="${l.id}" aria-label="Frente ${l.name}"><div class="squad enemy-squad">${enemy.lanes[l.id].map(u=>tokenUnit(u,l.id,1-room.seat)).join('')||'<span class="vacant enemy-vacant">◇</span>'}</div><div class="lane-divider"><b class="power enemy-power">${power(enemy,l.id)}</b><span class="lane-title" title="${l.reward}"><i>${l.icon}</i>${l.name}<small>${l.id==='court'?'INFLUÊNCIA':l.id==='crypt'?'SAQUE':'DANO DIRETO'}</small></span><b class="power own-power">${power(me,l.id)}</b></div><div class="squad player-squad">${me.lanes[l.id].map(u=>tokenUnit(u,l.id,room.seat)).join('')||`<button class="vacant" data-deploy="${l.id}" aria-label="Invocar em ${l.name}"><span>＋</span></button>`}</div><button class="drop-zone ${selected?.kind==='card'?'show-drop':''}" data-deploy="${l.id}" aria-label="Jogar carta em ${l.name}" ${!ready||selected?.kind!=='card'?'disabled':''}>${l.icon}<span>INVOCAR</span></button></section>`).join('')}</div><aside class="battle-left"><div class="deck-stack"><i></i><i></i><div>◈<b>${me.deckCount}</b></div><small>BARALHO</small></div><button data-modal="chronicle" class="history-button" title="Histórico">≋</button><div class="kill-count">☠ ${me.kills||0}<small>ABATES</small></div></aside><aside class="battle-right"><div class="frenzy-meter ${me.rage>=6?'charged':''}"><span>FRENESI</span><b>${me.rage}<small>/6</small></b><div>${Array.from({length:6},(_,i)=>`<i class="${i<me.rage?'filled':''}"></i>`).join('')}</div></div><button data-power="ultimate" class="ultimate-button ${selected?.kind==='ultimate'?'active':''}" ${!ready||me.rage<6||me.ultimateUsed?'disabled':''} title="5 de dano. +1 ataque aos aliados da frente até o fim da rodada. Vampiros também curam 3."><span>✹</span><small>${h.ultimate}</small></button><button data-pass class="end-turn" ${!ready?'disabled':''}><span>⚔</span><b>${me.passed?'AGUARDANDO':'ENCERRAR'}</b><small>RODADA</small></button><div class="combo-count"><span>COMBO</span>${[0,1,2].map(i=>`<i class="${i<me.combo?'lit':''}">◆</i>`).join('')}</div></aside><div class="battle-instruction turn-${turnMode}" role="status" aria-live="polite"><span class="turn-glyph">${turnMode==='active'?'⚔':turnMode==='enemy'?'☾':turnMode==='locked'?'✓':'◇'}</span><span class="turn-copy"><b>${turnTitle}</b><small>${instruction}</small></span>${selected?'<button data-cancel aria-label="Cancelar seleção">✕</button>':''}</div>${hero(me,room.seat)}<div class="player-abilities"><button class="skill-button ${selected?.kind==='skill'?'active':''}" data-power="skill" ${!ready||me.energy<2||me.skillUsed?'disabled':''} title="${h.description}"><span>${me.faction==='vampire'?'♦':'≋'}</span><b>2</b></button><small>${h.skill}</small></div><div class="energy-hud"><div class="energy-orb">${me.energy}</div><div><span>${FACTIONS[me.faction].resource.toUpperCase()}</span><div class="energy-pips">${Array.from({length:Math.min(7,room.round+2)},(_,i)=>`<i class="${i<me.energy?'filled':''}"></i>`).join('')}</div></div></div><div class="hand-dock"><div class="hand-fan count-${me.hand.length}">${me.hand.map((c,i)=>card(c.cardId,c.uid,i,me.hand.length)).join('')}</div></div><div class="battle-footer"><span>${room.mode==='duel'?`SALA <b>${room.roomId}</b>`:room.mode==='dungeon'?'DUNGEON · MALDIÇÃO: −1 VIDA / RODADA':'CAÇADA · RIVAL AUTOMÁTICO'}</span><small>ARRASTE PARA INVOCAR · CLIQUE PARA ATACAR · ESC CANCELA</small><span>${me.hand.length}/10 CARTAS</span></div>${room.waiting?`<div class="waiting-banner"><small>CONVIDE SEU RIVAL</small><strong>${room.roomId}</strong><p>Entre com este código em outro navegador ou janela anônima.</p></div>`:''}${room.phase==='finished'?resultHTML():''}<div id="effects" aria-hidden="true"></div></main>`;
}
function resultHTML(){const win=room.winner===room.seat,reward=room.rewards||{},loot=(reward.looted||[]).map(x=>`<span class="result-item-loot">⚒ ${esc(x)}</span>`).join(''),breaks=(reward.broken||[]).map(x=>`<span class="result-item-break">⚒ ${esc(x)}</span>`).join('');return `<div class="result-overlay"><div class="result-panel ${win?'victory':''}">${room.encounter?`<p class="realm-result">${esc(reward.realm?.message||'Sua aventura foi salva.')} ${reward.realm?.xp?`+${reward.realm.xp} XP DE EXPLORAÇÃO`:''}</p><button class="gold-button" data-return-realms>CONTINUAR A AVENTURA ↗</button>`:''}<div class="result-sigil">${room.winner===-1?'⚖':win?'♛':'☠'}</div><p class="overline">A NOITE COBROU SEU PREÇO</p><h1>${room.winner===-1?'EMPATE':win?'VITÓRIA':'DERROTA'}</h1><p>${win?'Seu nome foi escrito em sangue.':'As sombras ainda se lembram de você.'}</p><div class="result-loot"><b>+${reward.xp??(win?100:50)} XP</b><strong>+${reward.coins??0} MARCAS</strong><span>+${reward.dust??0} FRAGMENTOS</span><span>+${reward.scrap??0} SUCATA</span><span>${room.players[room.seat].kills} ABATES</span>${reward.items?`<strong>⚒ +${reward.items} PEÇA DE DUNGEON</strong>`:''}${loot}${breaks}${win&&room.mode==='dungeon'?'<strong>♜ COROA DO REI SEPULTADO</strong>':''}</div><button class="hunt-button" data-start="${['duel','realm'].includes(room.mode)?'practice':room.mode}"><span>CAÇAR NOVAMENTE</span></button><button class="text-button" data-home>VOLTAR AO REFÚGIO</button></div></div>`;}
function deckModalBody(){
  if(!profile?.decks)return '<p>Seu arsenal ainda está sendo preparado.</p>';
  if(!editingDeckId){return `<p>Decks de 20 cartas · mínimo ${DECK_RULES.minUnits} aliados e ${DECK_RULES.minAffordableUnits} aliados de custo 2 ou menos · até ${DECK_RULES.maxCopies} cópias (1 lendária). As cartas dos seus decks continuam disponíveis para outras listas.</p><div class="deck-list">${profile.decks.map(d=>`<article class="deck-row ${profile.activeDecks?.[d.faction]===d.id?'active':''}"><div class="deck-crest ${d.faction}">${art(d.faction)}</div><div><strong>${esc(d.name)}</strong><small>${FACTIONS[d.faction].name} · ${d.cards.length}/20 · ${analyzeDeck(d.cards).style}</small></div><button data-deck-edit="${d.id}">EDITAR</button>${profile.activeDecks?.[d.faction]===d.id?'<span class="deck-active">EM USO</span>':`<button data-deck-activate="${d.id}">EQUIPAR</button>`}</article>`).join('')}</div><div class="new-deck-row"><span>NOVA LISTA · escolha a facção e monte usando sua coleção.</span>${Object.keys(FACTIONS).map(id=>`<button data-deck-new="${id}">${id==='vampire'?'CORTE RUBRA':'ALCATEIA'}</button>`).join('')}</div>`;}
  const saved=profile.decks.find(d=>d.id===editingDeckId),f= saved?.faction||editingDeckFaction,draft=deckDraft||[],owned=profile.collection||{},items=profile.items||[],counts=countCards(draft),stats=analyzeDeck(draft);let error='';try{validateDeck(draft,f,owned,items);}catch(e){error=e.message;}
  const pool=Object.values(CARDS).filter(c=>(c.faction===f||c.faction==='neutral')&&matchesSearch(c)).sort((a,b)=>a.cost-b.cost||a.name.localeCompare(b.name));
  return `<div class="deck-editor-head"><button data-deck-back>← TODAS AS LISTAS</button><label>Nome da lista<input id="deck-name" maxlength="28" value="${esc(deckDraftName||saved?.name||'Meu deck')}"></label><div class="deck-ratio ${stats.balance>112?'high':stats.balance<78?'low':''}"><b>${stats.balance}</b><small>ORÇAMENTO MÉDIO</small></div></div><div class="deck-stats"><span>${draft.length}/20 CARTAS</span><span>${stats.units} ALIADOS</span><span>${stats.equipment}/${DECK_RULES.maxEquipment} ITENS</span><span>MÉDIA ${stats.averageCost} RECURSOS</span><span>${stats.synergyCards} SINERGIAS</span><strong>${stats.style}</strong></div><p class="deck-validation ${error?'':'valid'}">${error||'Lista legal · pronta para a caçada.'}</p>${searchTools()}<div class="deck-editor-columns"><section class="deck-current"><h3>NA LISTA <small>${draft.length}/20</small></h3>${Object.entries(counts).length?Object.entries(counts).sort((a,b)=>CARDS[a[0]].cost-CARDS[b[0]].cost).map(([id,n])=>`<div class="deck-card-row"><button class="deck-inspect" data-inspect="${id}" data-preview="${id}">${art(id,"mini-art")}<span>${CARDS[id].name}<small>${CARDS[id].cost} recursos · ${CARDS[id].rarity} · régua ${cardBalance(CARDS[id])}</small></span></button><b>×${n}</b><button data-card-remove="${id}" aria-label="Remover ${CARDS[id].name}">−</button></div>`).join(''):'<p class="empty-deck">Adicione cartas da coleção.</p>'}</section><section class="deck-pool"><h3>COLEÇÃO <small>FACÇÃO + RELÍQUIAS</small></h3>${pool.map(c=>{const n=counts[c.id]||0,ownedCount=ownedCardCount(c.id,owned,items),can=ownedCount>n&&n<cardLimit(c)&&draft.length<20;return `<div class="deck-card-row"><button class="deck-inspect" data-inspect="${c.id}" data-preview="${c.id}">${art(c.id,"mini-art")}<span>${c.name}<small>${c.cost} recursos · ${c.rarity} · régua ${cardBalance(c)} · ${n}/${ownedCount} na lista/coleção</small></span></button><button data-card-add="${c.id}" ${!can?'disabled':''} aria-label="Adicionar ${c.name}">＋</button></div>`;}).join('')}</section></div><div class="deck-editor-actions"><button class="gold-button" data-deck-save ${error?'disabled':''}>SALVAR LISTA</button>${saved?`<button class="menu-option" data-deck-activate="${saved.id}">EQUIPAR PARA ${f==='vampire'?'A CORTE':'A ALCATEIA'}</button>`:''}</div>`;
}
function modalHTML(){if(!modal)return '';let body='',title='';
  if(modal==='onboarding'){title='Seu juramento começa aqui';body=`<p>Escolha uma facção. Você recebe um deck completo de 20 cartas, duas peças iniciais vinculadas, 300 Marcas e acesso ao primeiro conjunto: <b>${CARD_SET.name}</b>.</p><div class="faction-switch onboarding-factions">${Object.keys(FACTIONS).map(id=>`<button data-faction="${id}" class="${id===faction?'active':''}">${art(id)}<span>${id==='vampire'?'CORTE RUBRA':'ALCATEIA DO ECLIPSE'}<small>${id==='vampire'?'Rituais, influência e drenagem.':'Matilha, feridas e pressão.'}</small></span></button>`).join('')}</div><label class="onboard-name">Nome do caçador<input id="onboard-name" maxlength="24" value="Caçador"></label><button class="hunt-button" data-onboard-create><span>RECEBER MEU DECK</span><b>⚔</b></button><small>Sem compra com dinheiro real. Boosters e cartas são ganhos jogando e usando Marcas/Fragmentos.</small>`;}
  if(modal==='duel'){title='Sangue contra sangue';body=`<p>Crie um duelo e escolha o risco compartilhado.</p><label class="risk-toggle"><input id="duel-risk" type="checkbox" ${duelRisk==='blood-oath'?'checked':''}><span><b>JURAMENTO DE SANGUE</b><small>Peças em aliados abatidos podem ser tomadas pelo carrasco. Sem esta opção, o equipamento só perde durabilidade.</small></span></label><button class="hunt-button" data-start="duel"><span>CRIAR DUELO 1 × 1</span></button><div class="modal-separator">OU ENTRE EM UMA SALA</div><form id="join-form"><label for="room-code">Código do duelo</label><div><input id="room-code" required maxlength="10" pattern="[a-fA-F0-9]{10}" placeholder="Código de 10 caracteres"><button class="gold-button" type="submit">ENTRAR</button></div><label class="risk-accept"><input id="accept-risk" type="checkbox"><span>Se o duelo exigir, aceito o Juramento de Sangue após ver o código com o anfitrião.</span></label></form><small>Use uma janela anônima para entrar como segundo jogador.</small>`;}
  if(modal==='guide'){title='A caçada em quatro movimentos';body=`<div class="guide-grid"><article><b>01</b><h3>Invoque</h3><p>Arraste uma carta para uma frente, ou clique na carta e depois no local. O custo sai do seu Sangue ou Fúria.</p></article><article><b>02</b><h3>Ataque</h3><p>Clique em um aliado pronto e depois no inimigo da mesma frente. Sem inimigos, ataque o líder. Ataques são gratuitos, uma vez por aliado por rodada, com revide simultâneo.</p></article><article><b>03</b><h3>Desperte</h3><p>Atacar e abater carrega Frenesi. Com 6, libere a suprema: 5 de dano e +1 ataque aos aliados da frente. O botão ao lado do seu líder usa a habilidade de 2 recursos, uma vez por rodada.</p></article><article><b>04</b><h3>Sobreviva</h3><p>Ao encerrar, aliados que ainda não atacaram trocam golpes automaticamente. Corte concede 2 Renome e cura 1; Catacumbas concede 1 Renome e loot; Caçada concede 1 Renome e causa 3 de dano. Empates não premiam. Depois, os recursos se renovam e cada jogador compra uma carta.</p></article></div><div class="guide-notes"><p><b>RPG:</b> aliados que sobrevivem a 1 / 3 abates em ataques diretos sobem para nível 2 / 3, ganhando +1 ataque e +2 vida em cada evolução. Cada aliado carrega até 2 equipamentos.</p><p><b>Combo:</b> jogue 3 cartas na mesma rodada para causar 2 de dano ao líder rival e ganhar 2 Frenesi.</p><p><b>Vitória:</b> derrube o líder ou alcance 12 Renome no confronto. Após a rodada 8, maior Renome vence; vida desempata. Morte simultânea é empate. Sangramento aplica dano no confronto e desaparece. Drenar cura pelo dano causado ao atacar, inclusive contra criaturas. Sem cartas no baralho, compras causam fadiga crescente.</p><p><b>Dungeon:</b> Mordrath tem 36 de vida e começa com uma sentinela. Sua maldição causa 1 de dano a cada nova rodada. Ao iniciar uma rodada com 18 de vida ou menos, fortalece seus aliados uma vez. Vença para obter um troféu permanente, sem bônus de poder.</p></div>`;}
  if(modal==='guide')body+=`<div class="guide-notes"><p><b>Turno:</b> ações alternam entre líderes até ambos encerrarem. Recursos começam em 3, sobem +1 por rodada e param em 7. Um aliado ataca sem custo uma vez por rodada; se ainda houver inimigo na frente, o ataque direto não alcança o líder. Habilidades custam 2 e a Suprema consome 6 Frenesi.</p><p><b>Dano e estados:</b> ataques contra criaturas trocam dano simultâneo; vida chega a zero e o abate é removido antes da conquista. Sangramento acumula e causa seu valor no confronto; Drenar cura pelo dano efetivamente causado. Equipamentos dão os atributos impressos por esta partida: até 2 por criatura e 1 no líder. Salto concede +2 ataque e permite um novo ataque. Suprema e sinergias dão bônus até o fim da rodada.</p><p><b>Relicário e risco:</b> equipamento tem 3 usos. No fim de uma caçada, peças equipadas perdem 1 de durabilidade; peças de criaturas abatidas perdem 2. No relicário, repare por Marcas, crie com Marcas + Sucata ou negocie peças sem vínculo no Mercado. O Pacto não transfere itens entre jogadores. O Juramento de Sangue exige que os dois aceitem e permite saquear uma peça não vinculada; a derrota também pode custar o equipamento usado pelo líder.</p><p><b>Sinergia:</b> Escrivã e Viúva respondem a mortes aliadas; Sanguinista e Marechal respondem a rituais; Corredor e Alfa respondem a novas invocações; Uivadora responde a sangramento. Cada sinergia aciona no máximo uma vez por rodada e exige a mesma frente.</p><p><b>Construção:</b> decks têm 20 cartas, ao menos 8 aliados e 2 aliados de custo 2 ou menos para mãos iniciais jogáveis; média até 4,5 recursos, até 6 equipamentos e cópias limitadas a 2 (1 lendária). Só entram cartas da facção e relíquias neutras. A régua no editor estima orçamento; orienta a curva sem alterar o combate. O saque de Catacumbas é uma cópia de item temporária da partida; vitórias na dungeon dão uma peça permanente.</p></div>`;
  if(modal==='collection'){title=`${CARD_SET.name} · coleção`;body=`<div class="collection-wallet"><b>${Object.values(profile?.collection||{}).reduce((a,n)=>a+n,0)+Object.values(profile?.items||[]).length} cartas e itens próprios</b><span>${profile?.dust||0} Fragmentos · ${profile?.scrap||0} Sucata</span><button data-modal="boosters">ABRIR BOOSTERS</button><button data-modal="decks">MONTAR DECK</button><button data-modal="market">RELICÁRIO & MERCADO</button></div>${searchTools()}<div class="collection-filters">${[['all','TODAS'],['vampire','VAMPIROS'],['werewolf','LOBISOMENS'],['neutral','RELÍQUIAS']].map(([id,name])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${name}</button>`).join('')}</div><div class="collection-grid">${Object.values(CARDS).filter(c=>(filter==='all'||c.faction===filter)&&matchesSearch(c)).map(c=>{const n=ownedCardCount(c.id,profile?.collection||{},profile?.items||[]),gearCost=ECONOMY.craftGear[c.rarity],cost=ECONOMY.craftDust[c.rarity],canCraft=c.type==='equipment'?profile?.coins>=gearCost.coins&&profile?.scrap>=gearCost.scrap:n<cardLimit(c)&&profile?.dust>=cost;return `<div class="collection-card">${card(c.id)}<p>${c.text}</p><small class="rarity-label ${c.rarity}">${c.rarity.toUpperCase()} · ${n} ${c.type==='equipment'?'PEÇA(S) UTILIZÁVEL(IS)':'CÓPIA(S)'}</small><button data-craft="${c.id}" ${!canCraft?'disabled':''}>${c.type==='equipment'?`CRIAR · ${gearCost.coins} MARCAS + ${gearCost.scrap} SUCATA`:`CRIAR · ${cost} FRAGMENTOS`}</button></div>`;}).join('')}</div>`;}
  if(modal==='boosters'){title='O selo da primeira noite';body=`<div class="booster-stage pack-${packState}"><div class="pack-pedestal"><div class="pack-aura"></div><img class="official-pack" src="/assets/pack/vespera-cutout.png" alt="Booster oficial Bloodmoon, Crônicas de Véspera, Edição I, cinco cartas"><span class="pack-rune">✧</span></div><div class="pack-story"><small>CRÔNICAS DE VÉSPERA · EDIÇÃO I</small><h3>O próximo juramento<br>está em suas mãos.</h3><p>Cinco cartas. Uma nova relíquia.<br>Rompa o selo e descubra o que a noite guardou.</p><div class="pack-contents"><span><b>2</b> COMUNS</span><span><b>1</b> INCOMUM</span><span><b>1</b> RARA+</span><span><b>1</b> ITEM</span></div><button class="hunt-button" data-buy-booster ${busy||profile.coins<ECONOMY.boosterCost?'disabled':''}><small>◈ ${ECONOMY.boosterCost} MARCAS · SALDO ${profile.coins}</small><span>${packState==='opening'?'ROMPENDO O SELO…':'ABRIR BOOSTER'}</span></button><details class="pack-odds"><summary>Conteúdo e probabilidades</summary><p>Premium: 78% rara, 19% épica, 3% lendária. Equipamento: 60% comum, 25% incomum, 12% raro, 3% épico. Cada equipamento é uma peça persistente com 3 de durabilidade. Duplicatas de cartas acima do limite viram fragmentos.</p></details></div></div>${packReveal.length&&packState!=='opening'?`<div class="reveal-toolbar"><h3>RECOMPENSAS DA NOITE</h3><button data-reveal-all>REVELAR TODAS</button></div><div class="pack-reveal">${packReveal.map((p,i)=>{const c=CARDS[p.id],revealed=revealedSlots.has(i);return `<article class="booster-pull ${p.rarity} ${revealed?'is-revealed':''}" style="--reveal-delay:${i*90}ms">${revealed?card(c.id):`<button class="sealed-card" data-reveal-slot="${i}" aria-label="Revelar carta ${i+1}"><i>☾</i><b>BLOODMOON</b><small>TOQUE PARA REVELAR</small></button>`}<small>${revealed?rarityNames[p.rarity]+' · '+(p.duplicate?'DUPLICATA':'ADICIONADA'):'DESTINO SELADO'}</small>${revealed&&p.duplicate?`<b>+${ECONOMY.duplicateDust[p.rarity]} FRAGMENTOS</b>`:''}${revealed&&p.item?'<b>RELÍQUIA · DURABILIDADE 3</b>':''}</article>`;}).join('')}</div>`:''}`;}
  if(modal==='decks'){title='Câmara de guerra';body=deckModalBody();}
  if(modal==='market'){title='Mercado do Crepúsculo';body=marketModalBody();}
  if(modal==='contracts'){title='Contratos da caçada';body=`<p>Contratos são objetivos recorrentes. As recompensas entram automaticamente ao cumprir cada marco.</p><div class="contract-list">${CONTRACTS.map(c=>{const n=profile?.contracts?.[c.id]||0,pct=Math.min(100,n/c.goal*100);return `<article><div><strong>${c.name}</strong><small>${c.label}</small></div><b>${n}/${c.goal}</b><span class="contract-track"><i style="width:${pct}%"></i></span><em>+${c.reward.coins||0} Marcas ${c.reward.dust?`· +${c.reward.dust} Fragmentos`:''}</em></article>`;}).join('')}</div><p class="economy-footnote">Uma vitória também concede XP; ao subir de nível, você recebe Marcas e Fragmentos. Derrotas pagam uma recompensa menor para manter a progressão sem premiar desistências.</p>`;}
  if(modal==='legacy'){title='Seu legado';body=`<div class="legacy-profile"><b>${profile?.level||1}</b><div><h3>${esc(profile?.name||'Caçador')}</h3><p>${profile?.xp||0} XP · ${profile?.matches||0} caçadas · ${profile?.wins||0} vitórias</p></div></div><progress value="${(profile?.xp||0)%300}" max="300"></progress><p>${300-(profile?.xp||0)%300} XP até o próximo nível.</p><div class="trophy ${(profile?.trophies||[]).includes('crown-of-the-buried')?'unlocked':''}">${art('boss')}<div><h3>Coroa do Rei Sepultado</h3><p>${(profile?.trophies||[]).includes('crown-of-the-buried')?'CONQUISTADA · Mordrath foi derrotado.':'Derrote o chefe da dungeon para conquistar.'}</p></div></div><p>Níveis e troféus registram sua jornada. Equipamentos e evolução dos aliados duram apenas a partida.</p>`;}
  if(modal==='chronicle'){title='Ecos do combate';body=`<ol class="chronicle">${[...room.log].reverse().map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;}
  if(modal==='pause'){title='A noite ainda não acabou';body=`<button class="hunt-button" data-close><span>VOLTAR À BATALHA</span></button><button class="menu-option" data-modal="guide">COMO JOGAR</button><button class="menu-option" data-home>REFÚGIO · MANTER PARTIDA</button><p>A partida continua disponível em “Retomar última partida”.</p>${room?.encounter?'<button class="menu-option" data-return-realms>VOLTAR AO MAPA · MANTER AVENTURA</button>':''}<button class="menu-option" data-concede>ABANDONAR · SEM RECOMPENSAS, COM DESGASTE</button>`;}
  if(modal.startsWith('art:')){const id=modal.slice(4),c=CARDS[id];title=c.name;body=`<div class="full-art-gallery">${CARD_ART[id]?`<img src="${CARD_ART[id]}" alt="${esc(c.name)}">`:art(id)}<p>${CARD_ART[id]?'Ilustração original · exibida na resolução disponível':'Arte provisória · ilustração exclusiva prevista no próximo lote'}</p></div>`;}
  if(modal.startsWith('card:')){const c=CARDS[modal.slice(5)],stats=c.type==='unit'?`<div class="inspect-stats"><span>⚔ ${c.attack} ATAQUE</span><span>♥ ${c.health} VIDA</span><span>♜ ${c.influence} INFLUÊNCIA</span></div>`:c.type==='equipment'?`<div class="inspect-stats"><span>⚔ +${c.attack} ATAQUE</span><span>♥ +${c.health} VIDA</span><span>⚒ PEÇA PERSISTENTE · ${ECONOMY.gearDurability} USOS</span></div><p>Em aliados, soma os atributos à criatura. Em seu líder, o ataque fortalece habilidades e a vida aumenta sua vida máxima.</p>`:`<div class="inspect-stats"><span>◈ ${c.cost} RECURSOS</span><span>${icon[c.type]}</span></div>`;title=c.name;body=`<div class="inspect-card full-card-inspect">${card(c.id)}<div class="inspect-copy"><small class="rarity-label ${c.rarity}">${c.rarity.toUpperCase()} · ${icon[c.type]} · CUSTO ${c.cost}</small><h3>${c.name}</h3>${stats}<p>${c.text}</p>${c.synergy?'<p class="inspect-synergy">✧ Sinergia na mesma frente · uma ativação por rodada. Bônus temporários expiram após o confronto.</p>':''}<blockquote>${c.flavor}</blockquote><button class="gold-button" data-full-art="${c.id}">AMPLIAR ILUSTRAÇÃO ↗</button><p class="art-status">${CARD_ART[c.id]?'ARTE ORIGINAL':'ARTE PROVISÓRIA · ILUSTRAÇÃO EXCLUSIVA PENDENTE'}</p><small>${FACTIONS[c.faction]?.name||'Relicário · Crônicas de Véspera'}</small></div></div>`;}
  return `<div class="modal-backdrop ${!room?'menu-backdrop':''} menu-${modal.split(':')[0]}"><section class="game-modal ${['collection','decks','boosters','market'].includes(modal)||modal.startsWith('card:')?'wide':''} ${modal==='decks'?'deck-modal':''} ${modal.startsWith('card:')?'card-inspection-modal':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button data-close class="modal-close" aria-label="Fechar">✕</button><div class="window-heading"><p class="overline">BLOODMOON · SANGUE & FÚRIA</p><h2>${title}</h2><span class="window-ornament">◆</span></div>${!room?`<nav class="window-navigation">${[['collection','ARSENAL'],['decks','DECKS'],['boosters','BOOSTERS'],['market','RELICÁRIO'],['contracts','CONTRATOS']].map(([id,label])=>`<button data-modal="${id}" class="${modal===id?'active':''}">${label}</button>`).join('')}</nav>`:''}${body}</section></div>`;
}
function bindInspectionTilt(){const face=app.querySelector('.full-card-inspect > .game-card');if(!face)return;let activePointer=null,startX=0,startY=0,lastY=0,gesture='pending',dragged=false,skipClick=false,clearSkipTimer=0;const reset=()=>{face.classList.remove('is-tilting');face.style.removeProperty('--inspect-tilt-x');face.style.removeProperty('--inspect-tilt-y');face.style.removeProperty('--inspect-shine-x');face.style.removeProperty('--inspect-shine-y');};const aim=(event)=>{const rect=face.getBoundingClientRect();if(!rect.width||!rect.height)return;const x=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height));face.style.setProperty('--inspect-tilt-x',`${((.5-y)*34).toFixed(2)}deg`);face.style.setProperty('--inspect-tilt-y',`${((x-.5)*34).toFixed(2)}deg`);face.style.setProperty('--inspect-shine-x',`${(x*100).toFixed(1)}%`);face.style.setProperty('--inspect-shine-y',`${(y*100).toFixed(1)}%`);face.classList.add('is-tilting');};face.addEventListener('pointerdown',event=>{if(event.button!==undefined&&event.button!==0)return;activePointer=event.pointerId;startX=event.clientX;startY=lastY=event.clientY;gesture='pending';dragged=false;if(event.pointerType==='touch')face.setPointerCapture?.(event.pointerId);});face.addEventListener('pointermove',event=>{if(event.pointerType==='touch'){if(activePointer!==event.pointerId)return;const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.hypot(dx,dy)>5)dragged=true;if(gesture==='pending'&&Math.hypot(dx,dy)>9)gesture=Math.abs(dy)>Math.abs(dx)*1.2?'scroll':'tilt';if(gesture==='scroll'){const panel=face.closest('.game-modal');if(panel)panel.scrollTop+=lastY-event.clientY;lastY=event.clientY;return;}}else if(activePointer===event.pointerId&&Math.hypot(event.clientX-startX,event.clientY-startY)>5)dragged=true;aim(event);});face.addEventListener('pointerup',event=>{if(activePointer!==event.pointerId)return;activePointer=null;reset();if(dragged){skipClick=true;clearTimeout(clearSkipTimer);clearSkipTimer=setTimeout(()=>skipClick=false,350);}});face.addEventListener('pointercancel',()=>{activePointer=null;dragged=false;reset();});face.addEventListener('pointerleave',event=>{if(event.pointerType!=='touch'&&activePointer===null)reset();});face.addEventListener('click',event=>{if(!skipClick)return;event.preventDefault();event.stopImmediatePropagation();skipClick=false;clearTimeout(clearSkipTimer);});}
function mountCardPreview(){if(!document.querySelector('#card-preview')){const preview=document.createElement('div');preview.id='card-preview';preview.className='card-preview';preview.setAttribute('aria-hidden','true');document.body.append(preview);}}
function bindHover(){const preview=document.querySelector('#card-preview');if(!preview)return;app.querySelectorAll('[data-preview]').forEach(el=>{const show=()=>{if(selected||busy||modal?.startsWith('card:')||modal?.startsWith('art:'))return;const c=CARDS[el.dataset.preview];if(!c)return;const box=el.getBoundingClientRect(),right=box.left<innerWidth/2;preview.innerHTML=`<div class="preview-card-face">${card(c.id)}</div><div class="preview-card-copy"><small class="rarity-label ${c.rarity}">${c.rarity.toUpperCase()} · ${icon[c.type]} · CUSTO ${c.cost}</small><strong>${esc(c.name)}</strong><p>${esc(c.text)}</p>${c.type==='unit'?`<span>⚔ ${c.attack} · ♥ ${c.health} · ♜ ${c.influence}</span>`:c.type==='equipment'?`<span>⚔ +${c.attack} · ♥ +${c.health} · ⚒ ${effectNames[c.gearEffect]||'RELÍQUIA'}</span>`:''}</div>`;preview.style.left=right?'auto':'18px';preview.style.right=right?'18px':'auto';preview.style.top=`${Math.max(12,Math.min(innerHeight-400,box.top+box.height/2-190))}px`;preview.classList.add('visible');};const hide=()=>preview.classList.remove('visible');el.addEventListener('mouseenter',show);el.addEventListener('focus',show);el.addEventListener('mouseleave',hide);el.addEventListener('blur',hide);});}
async function guarded(work){if(busy)return;busy=true;render();try{await work();}catch(e){toast(e.message);}finally{busy=false;render();}}
async function act(action){if(!canAct())return;const id=room.roomId,old=room.events.at(-1)?.id||0,frame=captureCombatFrame(action);selected=null;await guarded(async()=>{try{const next=await api(`/rooms/${id}/actions`,'POST',{version:room.version,action});room=next;render();await animateEvents(next.events.filter(e=>e.id>old),next.seat,frame);if(next.phase==='finished')profile=await api('/profile');}catch(e){frame.cardFlight?.remove();frame.sourceFlight?.remove();room=await api(`/rooms/${id}`);if(action.type==='play'){const held=room.players[room.seat].hand.find(c=>c.uid===action.uid);selected=held?{kind:'card',uid:held.uid,cardId:held.cardId}:null;}throw e;}});}
async function start(mode){const riskMode=mode==='duel'&&document.querySelector('#duel-risk')?.checked?'blood-oath':'covenant';duelRisk=riskMode;await guarded(async()=>{await ensureProfile();room=await api('/rooms','POST',{faction,mode,riskMode,deckId:profile.activeDecks?.[faction]});modal=null;selected=null;remember();playSound('start');});}
async function createDeckDraft(f){editingDeckId='new';editingDeckFaction=f;deckDraft=[];deckDraftName=f==='vampire'?'Novo juramento rubro':'Novo pacto da alcateia';render();}
async function saveDeckDraft(){const name=document.querySelector('#deck-name')?.value||deckDraftName;try{validateDeck(deckDraft||[],editingDeckFaction,profile.collection||{},profile.items||[]);}catch(e){toast(e.message);return;}await guarded(async()=>{const create=editingDeckId==='new',result=await api(create?'/decks':`/decks/${editingDeckId}`,create?'POST':'PUT',{name,cards:deckDraft});profile=result.profile;if(create)editingDeckId=result.deck.id;deckDraftName=name;deckDraft=[...result.deck.cards];toast('Deck salvo. Itens usados serão reservados e podem se desgastar na partida.');});}
